sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var sysId = request.pathParams.sys_id;
    var body = request.body.data;

    var gr = new GlideRecord('incident');
    if (gr.get(sysId)) {
        if (body.caller) gr.caller_id = body.caller;
        if (body.short_description) gr.short_description = body.short_description;
        if (body.description) gr.description = body.description;
        if (body.category) gr.category = body.category;
        if (body.priority) gr.priority = body.priority;

        gr.update();

        response.setStatus(200);
        response.setBody({
            message: "Incident updated successfully",
            sys_id: sysId
        });
    } else {
        response.setStatus(404);
        response.setBody({ error: "Incident record not found" });
    }
})(request, response);
